referenceSolutions.javascript:
function floorRegisterFirstQualifyingSlip(root, k) {
  const a=root; let out=[];
  if(a){const queue=[a];let head=0;while(head<queue.length){const end=queue.length;let s=0;while(head<end){const node=queue[head++];s+=node.val;if(node.left)queue.push(node.left);if(node.right)queue.push(node.right);}out.push(s);}}
  return out.find(x=>x>=k)??-1;
}

